import { readable } from 'svelte/store';
import { onDestroy } from 'svelte';
import { createActor } from 'xstate';

function useActorRef(logic, ...[options]) {
  const actorRef = createActor(logic, options).start();
  onDestroy(() => actorRef.stop());
  return actorRef;
}

function useActor(logic, ...[options]) {
  const actorRef = useActorRef(logic, options);
  let currentSnapshot = actorRef.getSnapshot();
  const snapshot = readable(currentSnapshot, set => {
    return actorRef.subscribe(nextSnapshot => {
      if (currentSnapshot !== nextSnapshot) {
        currentSnapshot = nextSnapshot;
        set(currentSnapshot);
      }
    }).unsubscribe;
  });
  return {
    snapshot,
    send: actorRef.send,
    actorRef
  };
}

/** @alias useActor */
function useMachine(machine, ...[options]) {
  return useActor(machine, options);
}

function defaultCompare(a, b) {
  return a === b;
}
const useSelector = (actor, selector, compare = defaultCompare) => {
  let sub;
  let prevSelected = selector(actor.getSnapshot());
  const selected = readable(prevSelected, set => {
    const onNext = snapshot => {
      const nextSelected = selector(snapshot);
      if (!compare(prevSelected, nextSelected)) {
        prevSelected = nextSelected;
        set(nextSelected);
      }
    };

    // Make sure the store gets updated when it's subscribed to.
    onNext(actor.getSnapshot());
    sub = actor.subscribe(onNext);
    return () => {
      sub.unsubscribe();
    };
  });
  return selected;
};

export { useActor, useActorRef, useMachine, useSelector };
